import {mutation,query} from "./_generated/server";
import {components} from "./_generated/api";
import {createThread} from "@convex-dev/agent";
import {v,ConvexError} from "convex/values";
const owner=async(ctx:any)=>{const i=await ctx.auth.getUserIdentity();if(!i||i.issuer!=="https://unrelated-task06-custom.example")throw new ConvexError("HOST_AUTH_REQUIRED");return i.subject;};
export const seed=mutation({args:{text:v.string()},handler:async(ctx,args)=>{const subject=await owner(ctx);const row=await ctx.db.query("hostNotes").withIndex("by_owner",q=>q.eq("owner",subject)).unique();if(row)return {noteId:row._id};const noteId=await ctx.db.insert("hostNotes",{owner:subject,text:args.text});const threadId=await createThread(ctx,components.hostAgent,{userId:subject,title:"unrelated host thread"});return {noteId,threadId};}});
export const list=query({args:{},handler:async(ctx)=>ctx.db.query("hostNotes").withIndex("by_owner",q=>q.eq("owner","host-owner")).collect()});
export const authenticated=query({args:{},handler:async(ctx)=>{const subject=await owner(ctx);return ctx.db.query("hostNotes").withIndex("by_owner",q=>q.eq("owner",subject)).collect();}});

